// ===== Default repo for manual runs (webhook callers send {"repo":"owner/repo"}) =====
const CONFIG = { repo: 'owner/repo', branch: '', max_files: 400, max_file_kb: 200, history_commits: 25 };

const raw = $input.first().json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : {};
const via_webhook = !!raw.headers;
const scan_id = 'scan_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const clamp = (v, d, lo, hi) => { const n = parseInt(v, 10); return isNaN(n) ? d : Math.max(lo, Math.min(hi, n)); };
const repo = String(body.repo || CONFIG.repo || '').trim().replace(/^https?:\/\/(www\.)?github\.com\//i, '').replace(/\.git$/i, '').replace(/\/+$/, '');
const branch = String(body.branch || CONFIG.branch || '').trim();
const fail = (error) => [{ json: { ok: false, error, via_webhook, scan_id, http_status: 400 } }];
const parts = repo.split('/');
if (parts.length !== 2 || !/^[A-Za-z0-9_.-]{1,100}$/.test(parts[0]) || !/^[A-Za-z0-9_.-]{1,100}$/.test(parts[1]) || /^\.+$/.test(parts[0]) || /^\.+$/.test(parts[1]) || repo === 'owner/repo')
  return fail('Provide a repository as "owner/repo" or a github.com URL, e.g. POST {"repo":"acme/payments-api"}');
if (branch && !/^[A-Za-z0-9._\/-]{1,100}$/.test(branch)) return fail('Invalid branch name');
return [{ json: { ok: true, repo, owner: parts[0], name: parts[1], branch, max_files: clamp(body.max_files, CONFIG.max_files, 10, 1000), max_file_kb: CONFIG.max_file_kb, history_commits: clamp(body.history_commits, CONFIG.history_commits, 0, 100), via_webhook, scan_id } }];

const p = $('Parse Input').first().json;
const r = $input.first().json || {};
const s = r.statusCode, b = r.body || {};
const err = (msg, st) => [{ json: { ok: false, error: msg, http_status: st, via_webhook: p.via_webhook, scan_id: p.scan_id } }];
if (s === 404) return err('Repository not found, or the GitHub token has no access to it', 404);
if (s === 401) return err('GitHub credential is invalid or expired', 401);
if (s === 403 || s === 429) return err('GitHub denied the request (rate limit or insufficient token permissions)', 429);
if (s !== 200) return err(`GitHub request failed (${s || 'network error'})`, 502);
return [{ json: { ...p, ok: true, default_branch: p.branch || b.default_branch || 'main', visibility: b.private ? 'private' : 'public', archived: !!b.archived, size_kb: b.size, html_url: b.html_url } }];

const e = $input.first().json;
const status = e.http_status || 400;
return [{ json: { status, via_webhook: !!e.via_webhook, response: { ok: false, scan_id: e.scan_id, error: e.error } } }];

