sd.secretscan.seen[c.repo] = Object.assign(sd.secretscan.seen[c.repo] || {}, Object.fromEntries(findings.map(f => [f.fp, Date.now()])));
const sk = Object.keys(sd.secretscan.seen[c.repo]); if (sk.length > 5000) sk.slice(0, sk.length - 5000).forEach(k => delete sd.secretscan.seen[c.repo][k]);

const pub = f => ({ id: f.id, severity: f.severity, confidence: f.conf, rule: f.rule, name: f.name, status: f.status, is_new: f.is_new, masked_value: f.masked,
  locations: f.locations.slice(0, 5).map(l => ({ path: l.path, line: l.line, commit: l.commit, author: l.author, date: l.date })), remediation: f.fix, ai_verdict: f.ai_verdict });
const actionable = findings.some(f => ['CRITICAL', 'HIGH'].includes(f.severity));
const response = { ok: true, scan_id: c.scan_id, repo: c.repo, visibility: c.visibility, branch: c.branch, scanned: { files: c.scanned.files, commits: c.scanned.commits }, secrets_found: findings.filter(f => !f.placeholder && f.severity !== 'INFO').length > 0, summary, warnings, findings: findings.slice(0, 200).map(pub) };

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[`*_~]/g, '');
const esc2 = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/`/g, "'");
const E = { CRITICAL: '🔴', HIGH: '🟠', MEDIUM: '🟡', LOW: '🔵', INFO: '⚪' };
const real = findings.filter(f => f.severity !== 'INFO' && !f.placeholder);
let t = `🔐 *Secret scan: ${esc(c.repo)}* (${c.visibility}, branch ${esc(c.branch)})\n`;
t += `Scanned ${c.scanned.files} files + ${c.scanned.commits} recent commits\n`;
t += real.length ? `*Found ${real.length} potential secret(s):* ${summary.critical} critical, ${summary.high} high, ${summary.medium} medium, ${summary.low} low  |  ${summary.removed_but_in_history} only in history${summary.new_since_last_scan < summary.total ? ', ' + summary.new_since_last_scan + ' new since last scan' : ''}\n` : `✅ No secrets found.\n`;
real.slice(0, 10).forEach(f => { const l = f.locations[0]; t += `${E[f.severity]} *${f.severity}* ${esc2(f.name)} — \`${esc2(l.path)}:${l.line}\` ${f.status === 'REMOVED_BUT_IN_HISTORY' ? '(removed, still in git history!)' : ''}\n`; });
if (real.length > 10) t += `…and ${real.length - 10} more\n`;
if (warnings.length) t += `\n⚠️ ${warnings.map(esc).join('; ')}\n`;
if (actionable) t += `\n*Deleting the file is not enough: revoke and rotate these credentials.* Approve to open a remediation issue in the repo (no secret values included):`;

const lines = real.slice(0, 40).map(f => { const l = f.locations[0]; return `| ${f.severity} | ${f.name} | \`${l.path}:${l.line}\` | ${f.status === 'IN_CURRENT_CODE' ? 'in current code' : 'removed, still in history'}${l.commit ? ' (' + l.commit + ')' : ''} | ${f.fix} |`; });
const issue_body = `## 🔐 Secret scan findings (automated)\n\n**Do not paste secret values in this issue.** Values are redacted.\n\n| Severity | Type | Location | Status | Fix |\n|---|---|---|---|---|\n${lines.join('\n')}\n\n### Required steps\n1. **Revoke / rotate every credential above first.** Deleting the line does not help: it remains in git history, forks and caches.\n2. Check the provider's audit logs for use by anyone else.\n3. Remove the secret from code; load it from a secrets manager or environment variable.\n4. (Optional) Rewrite history with git-filter-repo/BFG after rotation.\n5. Enable GitHub push protection and a pre-commit secret scanner.\n\n_Scan ${c.scan_id}_`;
return [{ json: { status: 200, response, actionable, slack_text: t, issue_title: `Security: ${real.length} potential secret(s) detected in repository`, issue_body } }];
